class BaseKeywordParser(abc.ABC):

    def parse(self, keyword):
        """
        Parse a single keyword.

        :param Keyword keyword: Keyword object.

        :return: PM Counter structure
        :rtype: dict
        """
        messages = get_messages(keyword)
        if not messages:
            return

        name = keyword.name
        return self._parse(name, messages)

    def _parse(self, name, messages):
        name = self._parse_name(name)
        if name != self.keyword_name:
            return

        return self._parse_messages(messages)

    def _parse_name(self, name):
        name = name.lower()
        name = name.replace("_", " ")
        name = name.rsplit(".", 1)[-1]
        return name

    def _parse_messages(self, messages):
        for message in messages:
            result = self._parse_message(message.message)
            if result:
                return result

    @abc.abstractmethod
    def _parse_message(self, message):
        """Method responsible for parsing keyword message."""

    @property
    @abc.abstractmethod
    def keyword_name(self):
        """Method returns keyword name to parse."""


class PMCounterKeywordParser(BaseKeywordParser):
    """Parser which is able to read keyword properties and generate PM counter structure for specified keyword."""

    REGEXP = re.compile(r"ID=(.*), VALUE=(.*), RESULT=(.*)")

    @property
    def keyword_name(self):
        """Method returns keyword name to parse."""
        return "report pm counter"

    def _parse_message(self, message):
        result = PMCounterKeywordParser.REGEXP.search(message)
        if result:
            id, value, result = result.groups()
            return {"id": id, "value": int(value), "result": result}


