class FailPathKeywordParser(BaseKeywordParser):

    @property
    def keyword_name(self):
        """Method returns keyword name to parse."""
        return None

    def parse(self, keyword):
        """Parse failed keyword name.

        :param Keyword keyword: Keyword object.

        :return: Failed keyword name
        :rtype: string
        """
        if "FAIL" in keyword.status:
            return keyword.name

    def _parse_message(self, message):
        pass


