class KpiResultsKeywordParser(BaseKeywordParser):
    """Parser which is able to read keyword properties and generate PM counter structure for specified keyword."""

    ENTITY_ID = r", ENTITY_ID=(?P<ENTITY_ID>.*)"
    COMPARISON_OPERATOR = r", COMPARISON_OPERATOR=(?P<COMPARISON_OPERATOR>.*)"
    VARIANT = r", VARIANT=(?P<VARIANT>.*)"
    TARGET = r", TARGET=(?P<TARGET>.*)"

    REGEXP_DYNAMIC_KPI = (
        r"TARGET=(?P<TARGET>.*), NAME=(?P<NAME>.*), VISIBLE_TO_DB=(?P<VISIBLE_TO_DB>.*), "
        r"VALUE=(?P<VALUE>.*), KPI_TYPE=(?P<TYPE>.*), DESCRIPTION=(?P<DESCRIPTION>.*), "
        r"CATEGORY=(?P<CATEGORY>.*), UNIT=(?P<UNIT>.*)"
    )

    REGEXP_DYNAMIC_KPI_v1 = re.compile(
        REGEXP_DYNAMIC_KPI + ENTITY_ID + COMPARISON_OPERATOR
    )
    REGEXP_DYNAMIC_KPI_v2 = re.compile(REGEXP_DYNAMIC_KPI + ENTITY_ID)
    REGEXP_DYNAMIC_KPI_v3 = re.compile(REGEXP_DYNAMIC_KPI + COMPARISON_OPERATOR)
    REGEXP_DYNAMIC_KPI_v4 = re.compile(REGEXP_DYNAMIC_KPI)

    REGEXP_SOURCE_BASED = r"ID=(?P<ID>.*), VALUE=(?P<VALUE>.*), SOURCE=(?P<SOURCE>.*)"

    REGEXP_SOURCE_BASED_v1 = re.compile(
        REGEXP_SOURCE_BASED + TARGET + VARIANT + ENTITY_ID
    )
    REGEXP_SOURCE_BASED_v2 = re.compile(REGEXP_SOURCE_BASED + TARGET + VARIANT)
    REGEXP_SOURCE_BASED_v3 = re.compile(REGEXP_SOURCE_BASED + TARGET + ENTITY_ID)
    REGEXP_SOURCE_BASED_v4 = re.compile(REGEXP_SOURCE_BASED + TARGET)
    REGEXP_SOURCE_BASED_v5 = re.compile(REGEXP_SOURCE_BASED + VARIANT + ENTITY_ID)
    REGEXP_SOURCE_BASED_v6 = re.compile(REGEXP_SOURCE_BASED + VARIANT)
    REGEXP_SOURCE_BASED_v7 = re.compile(REGEXP_SOURCE_BASED + ENTITY_ID)
    REGEXP_SOURCE_BASED_v8 = re.compile(REGEXP_SOURCE_BASED)

    KPI_REGEX = [
        REGEXP_DYNAMIC_KPI_v1,
        REGEXP_DYNAMIC_KPI_v2,
        REGEXP_DYNAMIC_KPI_v3,
        REGEXP_DYNAMIC_KPI_v4,
        REGEXP_SOURCE_BASED_v1,
        REGEXP_SOURCE_BASED_v2,
        REGEXP_SOURCE_BASED_v3,
        REGEXP_SOURCE_BASED_v4,
        REGEXP_SOURCE_BASED_v5,
        REGEXP_SOURCE_BASED_v6,
        REGEXP_SOURCE_BASED_v7,
        REGEXP_SOURCE_BASED_v8,
    ]

    @property
    def keyword_name(self):
        """Method returns keyword name to parse."""
        return "report kpi results"

    def _parse_message(self, message):
        for regex in KpiResultsKeywordParser.KPI_REGEX:
            result = regex.search(message)
            if result:
                params = {}
                for param, value in result.groupdict().items():
                    if param == "VARIANT":
                        value = json.loads(value)
                    params[param.lower()] = value
                return params


