class SystemUnderTestParser(BaseKeywordParser):
    REGEXP = re.compile(
        r"Add (?P<TYPE>BTS): (?P<ALL_ARGS>.*)"
    )  # In the future (?P<TYPE>BTS|FHGW|UE)

    @property
    def keyword_name(self):
        return ""

    def _parse_message(self, message):
        result = SystemUnderTestParser.REGEXP.search(message)
        if result:
            params = {"type": result.group("TYPE").lower()}
            all_args = result.group("ALL_ARGS")
            for arg in all_args.split(", "):
                key, value = arg.split("=")
                params[key.lower()] = value
            return params


class BTSParser(SystemUnderTestParser):

    @property
    def keyword_name(self):
        """Method returns keyword name to parse."""
        return "add bts to report"


