class Scanner:

    def scan_for_counters(self, test):
        """
        Method used for scanning for PM Counters in test

        :param TestCase         test:   Test case object generated by the Robot Framework.
        """
        pm_counter_visitor = KeywordsVisitor(PMCounterKeywordParser())
        keywords = get_keywords(test)
        return pm_counter_visitor.build(keywords)

    def scan_for_kpi_results(self, test):
        """
        Method used for scanning for KPI results in test

        :param TestCase         test:   Test case object generated by the Robot Framework.
        """
        kpi_result_visitor = KeywordsVisitor(KpiResultsKeywordParser())
        keywords = get_all_keywords(test)
        return kpi_result_visitor.build(keywords)

    def scan_for_steps(self, test):
        """
        Method used for scanning for steps in test

        :param TestCase         test:   Test case object generated by the Robot Framework.
        """
        return self._get_steps(test)

    def _get_steps(self, test):
        return [
            {
                "name": self._get_keyword_step(keyword),
                "result": self._convert_result(keyword.status),
                "link": "",
                "fail_log_path": self._build_fail_log_path_table(keyword),
                "logs": self._build_logs_table(keyword),
            }
            for keyword in get_all_keywords(test)
        ]

    def _convert_result(self, status):
        """
        The status is `NOT_RUN` in RF<4.0.0 and `NOT RUN` in newer versions
        """
        mapping = {
            "PASS": "passed",
            "FAIL": "failed",
            "NOT_RUN": "not run",
            "NOT RUN": "not run",
        }
        return mapping[status]

    def _get_keyword_step(self, keyword):
        keyword_name = self._remove_library_info(keyword.name)
        if keyword.args:
            return shorten_text("    ".join([keyword_name] + list(keyword.args)))
        return shorten_text(keyword_name)

    def _remove_library_info(self, keyword):
        if "." in keyword:
            parts = keyword.split(".")
            return "".join(parts[1:])
        return keyword

    def _build_fail_log_path_table(self, keyword):
        fail_log_path_parser = KeywordsVisitor(FailPathKeywordParser())
        return fail_log_path_parser.build_fail_log_path([keyword])

    def _build_logs_table(self, keyword):
        ret_list = []
        log_info_keyword_parser = KeywordsVisitor(LogInfoKeywordParser())
        for index, step in enumerate(log_info_keyword_parser.build([keyword])):
            if index < 9:
                ret_list.append(step)
            else:
                ret_list.append("(...)")
                break
        return ret_list

    def scan_for_reference_configuration_id(self, test):
        """
        Method used for scanning for Reference Configuration ID in test

        :param TestCase         test:   Test case object generated by the Robot Framework.
        """

        ref_configuration_id_visitor = KeywordsVisitor(RefConfigurationIdParser())
        result = ref_configuration_id_visitor.build(get_all_keywords(test))
        if result:
            return result[0]

    def scan_for_snapshot_location_in_test_keywords(self, test):
        """
        Method used for scanning for Snapshot location in test keywords

        :param TestCase   test:   Test case object generated by the Robot Framework.
        """

        snapshot_location_visitor = KeywordsVisitor(SnapshotLocationParser())
        keywords = get_all_keywords(test)
        return snapshot_location_visitor.build(keywords)

    def scan_for_snapshot_location_in_suite_setup_and_teardown_keywords(self, suite):
        """
        Method used for scanning for Snapshot location in Suite Setup and Teardowns keywords

        :param Suite   suite:   Suite object generated by the Robot Framework.
        """

        snapshot_location_visitor = KeywordsVisitor(SnapshotLocationParser())
        keywords = get_suite_setup_and_teardown_keywords(suite)
        return snapshot_location_visitor.build(keywords)

    def scan_for_syslog_location_in_test_keywords(self, test):
        """
        Method used for scanning for SysLog location in test keywords

        :param TestCase   test:   Test case object generated by the Robot Framework.
        """

        syslog_location_visitor = KeywordsVisitor(SysLogLocationParser())
        keywords = get_all_keywords(test)
        return syslog_location_visitor.build(keywords)

    def scan_for_syslog_location_in_suite_setup_and_teardown_keywords(self, suite):
        """
        Method used for scanning for SysLog location in Suite Setup and Teardowns keywords

        :param Suite   suite:   Suite object generated by the Robot Framework.
        """

        syslog_location_visitor = KeywordsVisitor(SysLogLocationParser())
        keywords = get_suite_setup_and_teardown_keywords(suite)
        return syslog_location_visitor.build(keywords)

    def scan_for_system_under_test(self, test):
        """
        Method used for scanning for System Under Test in test keywords

        :param TestCase   test:   Test case object generated by the Robot Framework.
        """

        def remove_duplicates(all_results):
            unique_results_dict = {result["id"]: result for result in all_results}
            return list(unique_results_dict.values())

        results = []
        for parser in [
            BTSParser()
        ]:  # In the future FHGWParser(), UEParser() can be added
            visitor = KeywordsVisitor(parser)
            parser_result = visitor.build(get_all_keywords(test))
            if parser_result:
                unique_results = remove_duplicates(parser_result)
                results.extend(unique_results)
                diff_result = [
                    record for record in parser_result if record not in unique_results
                ]
                if diff_result:
                    logger.warning(
                        f"Duplicated IDs removed from system_under_test: {diff_result}"
                    )

        return results

    def scan_for_hw_config(self, test):
        """
        Method used for scanning for HW config in test

        :param TestCase         test:   Test case object generated by the Robot Framework.
        """

        hw_config_visitor = KeywordsVisitor(ENBHardwareConfigKeywordParser())
        keywords = get_keywords(test)
        result = hw_config_visitor.build(keywords)
        if result:
            return result[0]

